                                      bool no_trailing, uint8_t const alphabet[static UINT8_MAX]);
#define         fr_base16_decode(_err, _out, _in, _no_trailing) \
                fr_base16_decode_nstd(_err, _out, _in, _no_trailing, fr_base16_alphabet_decode_mc)

